// Order the Steps kit
function moveOrder(btn, direction) {
  const card = btn.closest('.order-card');
  if (card.classList.contains('locked')) return;
  const sibling = direction === -1 ? card.previousElementSibling : card.nextElementSibling;
  if (!sibling) return;
  const list = card.parentElement;
  if (direction === -1) list.insertBefore(card, sibling);
  else list.insertBefore(sibling, card);
  updateOrderButtons();
  clearOrderState();
}
function updateOrderButtons() {
  const cards = document.querySelectorAll('#orderList .order-card');
  cards.forEach((c, i) => {
    const [up, down] = c.querySelectorAll('.order-buttons button');
    up.disabled = (i === 0);
    down.disabled = (i === cards.length - 1);
  });
}
function clearOrderState() {
  document.querySelectorAll('.order-card').forEach(c => c.classList.remove('correct', 'incorrect'));
  document.getElementById('orderStatus').textContent = '';
}
function checkOrder() {
  const cards = document.querySelectorAll('#orderList .order-card');
  let allCorrect = true;
  cards.forEach((c, i) => {
    const expected = parseInt(c.dataset.correctPos, 10);
    c.classList.remove('correct', 'incorrect');
    if (expected === i + 1) c.classList.add('correct');
    else { c.classList.add('incorrect'); allCorrect = false; }
  });
  const status = document.getElementById('orderStatus');
  if (allCorrect) {
    status.textContent = '✓ Perfect order: every step only uses points that already exist.';
    cards.forEach(c => c.classList.add('locked'));
  } else {
    const numCorrect = document.querySelectorAll('.order-card.correct').length;
    status.textContent = `${numCorrect}/${cards.length} in the right place. Which point does each step need?`;
  }
}
function shuffleOrder() {
  const list = document.getElementById('orderList');
  const cards = Array.from(list.children);
  for (let i = cards.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [cards[i], cards[j]] = [cards[j], cards[i]];
  }
  cards.forEach(c => { c.classList.remove('locked'); list.appendChild(c); });
  updateOrderButtons();
  clearOrderState();
}
function showOrderAnswer() {
  const list = document.getElementById('orderList');
  const cards = Array.from(list.children);
  cards.sort((a, b) => parseInt(a.dataset.correctPos, 10) - parseInt(b.dataset.correctPos, 10));
  cards.forEach(c => { list.appendChild(c); c.classList.add('correct'); c.classList.add('locked'); });
  updateOrderButtons();
  document.getElementById('orderStatus').textContent = 'Answer shown.';
}
updateOrderButtons();

// Error Analysis kit
let errFound = false;
function pickErrLine(el) {
  if (errFound || el.classList.contains('dimmed')) return;
  if (el.dataset.isError === 'true') {
    el.classList.add('flagged-correct');
    errFound = true;
    document.querySelectorAll('.err-line').forEach(o => { if (o !== el) o.classList.add('dimmed'); });
    document.getElementById('errFeedback').classList.add('visible');
  } else {
    el.classList.add('flagged-wrong');
    setTimeout(() => el.classList.remove('flagged-wrong'), 600);
  }
}
function checkErrCorrection() {
  const input = document.getElementById('errCorrection');
  const expected = document.querySelector('.err-line[data-is-error="true"]').dataset.correctLine;
  const norm = s => (s || '').toLowerCase().replace(/\s+/g, '').replace(/(cm)$/, '');
  const msg = document.getElementById('errStatusMsg');
  input.classList.remove('correct', 'incorrect');
  if (norm(input.value) === norm(expected)) {
    input.classList.add('correct');
    msg.textContent = '✓ Correct. Line 3 should read: compass on B, width 3 cm (the same width as the arc from A). Now AP = BP and both angles are 35°.';
  } else {
    input.classList.add('incorrect');
    msg.textContent = '✗ Not quite. The arc from B must match the width of the arc from A in line 2.';
  }
}

// Place the strategies in their teaching positions: Order the Steps straight after
// the We Do (combine the two algorithms), Error Analysis straight after the Quick Check.
(function () {
  const ord = document.getElementById('orderSection');
  const wd = document.getElementById('weDoGrid');
  const wdSec = wd && wd.closest('section');
  if (ord && wdSec) wdSec.after(ord);
  const err = document.getElementById('errSection');
  const cp = document.getElementById('checkpointGrid');
  const cpSec = cp && cp.closest('section');
  if (err && cpSec) cpSec.after(err);
})();

// Topic-specific instructions for the frame's fixed section text
(function () {
  const set = (sel, html) => { const el = document.querySelector(sel); if (el) el.innerHTML = html; };
  set('#tier1-body .sec-desc', 'Run the construction algorithms by hand. Type just the number for angles and lengths, or a single letter where you are asked to choose.');
  set('#tier2-body .sec-desc', 'Loops, decisions and combined constructions. Trace each algorithm line by line. Type a number, <code>yes</code>/<code>no</code>, or a single letter.');
  set('#tier3-body .sec-desc', 'The sign shop\'s engraver: count the instructions, then cost the job and the refinement. Type just the number (no $).');
  const wd = document.getElementById('weDoGrid');
  const tip = wd && wd.parentElement.querySelector('.parts-instructions');
  if (tip) tip.innerHTML = '💡 <strong>Why we do it this way:</strong> the arcs from O and A have the <strong>same width</strong>, so OA = OB = AB and triangle OAB is equilateral. That is a theorem doing the measuring for us, so no protractor is needed. Counting instructions tells the animator how many frames to draw.';
  const m = document.getElementById('matchArea');
  const md = m && m.parentElement.querySelector('.sec-desc');
  if (md) md.innerHTML = 'Click a construction, then click the angle it produces. There are five matching pairs.';
})();
